//! # Confidential Token -- Noir Primitives
//!
//! Shared cryptographic primitives consumed by the six circuits described in
//! Section 7 of the design document (Register, Withdraw, Transfer, SpenderTransfer,
//! SetSpender, RevokeSpender).
//!
//! Every constraint that involves a Pedersen commitment, a Poseidon2 hash with
//! domain separation, an ECDH derivation, or a 128-bit range check funnels
//! through one of the helpers exported here. Circuits never hash raw --
//! `poseidon_with_domain` is the only Poseidon entry point.
//!
//! ## Background: BN254, Grumpkin, and why this works in-circuit
//!
//! An elliptic curve is defined over a *base field* and has a *scalar field*
//! of the same size as its prime-order subgroup. Noir circuits, when targeting
//! the Barretenberg backend (UltraHonk), operate natively over the **BN254
//! scalar field**, written `F_r` (Noir's built-in `Field` type *is* `F_r`).
//!
//! **Grumpkin** is a curve specifically constructed so that its *base field*
//! equals BN254's *scalar field*. That means Grumpkin point coordinates are
//! `F_r` elements -- the same field the circuit is already working over. So
//! Grumpkin point arithmetic inside a Noir circuit is native field
//! arithmetic. This is what makes ! Pedersen commitments and ECDH cheap in
//! this design.
//!
//! Grumpkin's equation is `y^2 = x^3 - 17`. For a longer write-up, see
//! Aztec's primer:
//! <https://aztecprotocol.github.io/aztec-connect/primitives.html#2-grumpkin---a-curve-on-top-of-bn-254-for-snark-efficient-group-operations>
//!
//! ## Generators
//!
//! Both generators below come from Barretenberg's standard Pedersen domain
//! ("DEFAULT_DOMAIN_SEPARATOR") via `std::hash::derive_generators`, so
//! `commit(v, r)` is point-for-point identical to
//! `std::hash::pedersen_commitment([v, r])`. The numeric values are extracted
//! via the `print_generators` test (run
//! `nargo test print_generators --show-output`) so they are reproducible by
//! anyone with a Noir toolchain -- no off-chain trust required.

mod tests;

use std::embedded_curve_ops::{EmbeddedCurvePoint, EmbeddedCurveScalar, multi_scalar_mul};
use std::hash::poseidon2_permutation;

// ################## GENERATORS ##################

/// Barretenberg's Pedersen generator at index 0 of the "DEFAULT_DOMAIN_SEPARATOR"
/// domain. Equivalent to `derive_generators("DEFAULT_DOMAIN_SEPARATOR", 0)[0]`.
pub global G: EmbeddedCurvePoint = EmbeddedCurvePoint {
    x: 0x083e7911d835097629f0067531fc15cafd79a89beecb39903f69572c636f4a5a,
    y: 0x1a7f5efaad7f315c25a918f30cc8d7333fccab7ad7c90f14de81bcc528f9935d,
    is_infinite: false,
};

/// Barretenberg's Pedersen generator at index 1 of the "DEFAULT_DOMAIN_SEPARATOR"
/// domain. Equivalent to `derive_generators("DEFAULT_DOMAIN_SEPARATOR", 0)[1]`.
/// No known discrete-log relation to G (each is the output of Barretenberg's
/// hash-to-curve on the domain separator + index).
pub global H: EmbeddedCurvePoint = EmbeddedCurvePoint {
    x: 0x054aa86a73cb8a34525e5bbed6e43ba1198e860f5f3950268f71df4591bde402,
    y: 0x209dcfbf2cfb57f9f6046f44d71ac6faf87254afc7407c04eb621a6287cac126,
    is_infinite: false,
};

// ################## CONSTANTS ##################

/// Poseidon2 sponge Initialization Vector (IV) multiplier:
/// `iv = (input_length as Field) * 2^64`. Matches Noir stdlib's
/// `Poseidon2Hasher` and Barretenberg's Poseidon2 sponge.
global POSEIDON2_IV_BASE: Field = 18446744073709551616; // 2^64

/// Domain separation tags (Section 13 of the design document). The integer
/// values are the cross-language contract -- they appear as the first absorbed
/// element in every Poseidon2 call and the SDK must use the exact same numbers.
/// The names spell out what the design doc abbreviates; the table below maps
/// design-doc notation to the constant defined here.
///
/// | Design doc        | Value | Constant                          |
/// |:------------------|:------|:----------------------------------|
/// | `delta_addr`      | 1     | `ADDRESS`                         |
/// | `delta_vk`        | 2     | `VIEWING_KEY`                     |
/// | `delta_dvk`       | 3     | `DELEGATION_VIEWING_KEY`          |
/// | `delta_spend_r`   | 4     | `SPEND_RANDOMNESS`                |
/// | `delta_transfer_blind`  | 5     | `TRANSFER_BLINDING`                     |
/// | `delta_transfer_amount` | 6     | `TRANSFER_AMOUNT`                       |
/// | `delta_enc_bal`   | 7     | `ENCRYPTED_BALANCE`               |
/// | `delta_enc_allow` | 8     | `ENCRYPTED_ALLOWANCE`             |
/// | `delta_allow_r`   | 9     | `ALLOWANCE_RANDOMNESS`            |
/// | `delta_esc_dvk`   | 10    | `ESCROWED_DELEGATION_VIEWING_KEY` |
/// | `delta_aud_s`     | 11    | `AUDITOR_SENDER`                  |
/// | `delta_aud_r`     | 12    | `AUDITOR_RECIPIENT`               |
/// | `delta_ecdh`      | 13    | `ECDH_SHARED_SECRET`              |
pub mod domain {
    /// Soroban Address compression into a single `F_r` Field:
    /// `address_to_field(a) = Poseidon2(ADDRESS, lo(a), hi(a))`.
    /// Section 2.7 (`delta_addr`). The contract computes `addr_f` and `op_i`
    /// off-circuit via this tag; circuits consume the resulting Field directly.
    pub global ADDRESS: Field = 1;
    /// Viewing-key derivation: `vk = Poseidon2(VIEWING_KEY, sk, addr_f)`.
    /// Section 4.2 (`delta_vk`).
    pub global VIEWING_KEY: Field = 2;
    /// Delegation viewing-key derivation:
    /// `dvk = Poseidon2(DELEGATION_VIEWING_KEY, vk, op_i)`. Section 4.4 (`delta_dvk`).
    pub global DELEGATION_VIEWING_KEY: Field = 3;
    /// Deterministic randomness for the new spendable balance:
    /// `r' = Poseidon2(SPEND_RANDOMNESS, vk, sigma)`. Constraints W5/T10/S9/V6 (`delta_spend_r`).
    pub global SPEND_RANDOMNESS: Field = 4;
    /// ECDH-derived blinding for the transfer commitment:
    /// `r_transfer = Poseidon2(TRANSFER_BLINDING, s, sigma)`. Constraints T7/O7 (`delta_transfer_blind`).
    pub global TRANSFER_BLINDING: Field = 5;
    /// Mask for the encrypted transfer amount:
    /// `v_tilde = v_transfer + Poseidon2(TRANSFER_AMOUNT, s, sigma)`. Constraints T9/O9 (`delta_transfer_amount`).
    pub global TRANSFER_AMOUNT: Field = 6;
    /// Mask for the encrypted balance scalar:
    /// `b_tilde = v_new + Poseidon2(ENCRYPTED_BALANCE, vk, sigma)`.
    /// Constraints W7/T12/S11/V8 (`delta_enc_bal`).
    pub global ENCRYPTED_BALANCE: Field = 7;
    /// Mask for the encrypted allowance scalar:
    /// `a_tilde = v_a + Poseidon2(ENCRYPTED_ALLOWANCE, dvk, sigma_a)`.
    /// Constraints S8/O12 (`delta_enc_allow`).
    pub global ENCRYPTED_ALLOWANCE: Field = 8;
    /// Deterministic randomness for the spender allowance:
    /// `r_a = Poseidon2(ALLOWANCE_RANDOMNESS, dvk, sigma_a)`.
    /// Constraints S6/O3/O10 (`delta_allow_r`).
    pub global ALLOWANCE_RANDOMNESS: Field = 9;
    /// Delegation-key escrow mask (spender ECDH):
    /// `Poseidon2(ESCROWED_DELEGATION_VIEWING_KEY, s, op_i)`.
    /// Constraint S12, Section 7.11 (`delta_esc_dvk`).
    pub global ESCROWED_DELEGATION_VIEWING_KEY: Field = 10;
    /// Sender or owner-auditor channel tag for Poseidon2 sponge masks
    /// (Section 2.5, Section 8.1). Squeeze 1 yields the amount mask (where
    /// applicable); squeeze 2 yields the balance/allowance checkpoint mask.
    /// Constraints W_a3 / T_a6 / S_a3 / V_a3 / O_a6 (`delta_aud_s`).
    pub global AUDITOR_SENDER: Field = 11;
    /// Recipient-auditor channel tag for Poseidon2 sponge masks
    /// (Section 2.5, Section 8.1). Squeeze 1 yields the amount mask; squeeze
    /// 2 yields the per-transfer Pedersen randomness mask.
    /// Constraints T_a2 / O_a2 (`delta_aud_r`).
    pub global AUDITOR_RECIPIENT: Field = 12;
    /// ECDH shared-secret scalar extraction:
    /// `s = Poseidon2(ECDH_SHARED_SECRET, S.x, S.y)`.
    /// Section 2.4 (`delta_ecdh`). See [`ecdh`].
    pub global ECDH_SHARED_SECRET: Field = 13;
}

// ################## CORE PRIMITIVES ##################

/// Pedersen commitment `v*G + r*H` on Grumpkin. Section 2.3.
pub fn commit(value: Field, randomness: Field) -> EmbeddedCurvePoint {
    multi_scalar_mul(
        [G, H],
        [EmbeddedCurveScalar::from_field(value), EmbeddedCurveScalar::from_field(randomness)],
    )
}

/// Scalar multiplication `s*P` on Grumpkin. Used for `Y = sk*H`, `PVK = vk*H`,
/// `R_e = r_e*H`, and as the building block under `ecdh`.
pub fn scalar_mul(scalar: Field, point: EmbeddedCurvePoint) -> EmbeddedCurvePoint {
    multi_scalar_mul([point], [EmbeddedCurveScalar::from_field(scalar)])
}

/// ECDH shared-secret scalar extraction per Section 2.4: computes
/// `S = scalar * P` and binds both coordinates into the output via the
/// Poseidon funnel, `s = Poseidon2(ECDH_SHARED_SECRET, S.x, S.y)`.
///
/// Absorbing `S.y` removes the negation invariance of an x-only extraction:
/// `P` and `-P = (P.x, -P.y)` share an x-coordinate, so `(scalar * P).x`
/// alone maps a key and its negation (`-PVK = (-vk) * H`, itself a valid,
/// canonical registration) to the same shared secret for every scalar.
/// The absorb `[tag, S.x, S.y]` fills exactly one rate-3 block, so the
/// binding costs a single Poseidon2 permutation.
///
/// Use this whenever the *scalar* shared secret is what downstream Poseidon
/// helpers expect (every `derive_transfer_blind` / `encrypt_amount` /
/// `encrypt_auditor_*` call). When the full shared-secret *point* is needed,
/// reach for `scalar_mul` directly.
pub fn ecdh(scalar: Field, point: EmbeddedCurvePoint) -> Field {
    let s = scalar_mul(scalar, point);
    poseidon_with_domain(domain::ECDH_SHARED_SECRET, [s.x, s.y])
}

/// Asserts `p` is on Grumpkin AND not the identity. Use this for every
/// public-input *key* (Section 7.1 point 4: `R_e`, `Y`, `PVK`, `K_aud` must all
/// satisfy `P != O`). The identity element collapses ECDH (`S = O` regardless
/// of the secret scalar), so accepting it would let an adversary publish a key
/// for which every shared secret is known.
pub fn assert_on_curve_non_identity(p: EmbeddedCurvePoint) {
    assert(!p.is_infinite);
    assert(p.y * p.y == p.x * p.x * p.x - 17);
}

// ################## POSEIDON2 FUNNEL ##################

/// Poseidon2 sponge with rate=3, capacity=1, matching Noir stdlib's hasher and
/// Barretenberg's Poseidon2 sponge. IV = `len * 2^64` placed at the capacity
/// position; absorb `RATE` field elements per permutation; squeeze `state[0]`.
/// The empty input still applies the squeeze permutation, returning
/// `poseidon2_permutation([0, 0, 0, 0], 4)[0]` -- the same convention as the
/// on-chain sponge, which always permutes before squeezing. That branch is
/// comptime-dead for every `M >= 1` instantiation, and `poseidon_with_domain`
/// guarantees `M >= 1` on every reachable path.
fn sponge<let M: u32>(inputs: [Field; M]) -> Field {
    let iv: Field = (M as Field) * POSEIDON2_IV_BASE;
    let mut state: [Field; 4] = [0, 0, 0, iv];

    let full: u32 = M / 3;
    for i in 0..full {
        state[0] += inputs[i * 3];
        state[1] += inputs[i * 3 + 1];
        state[2] += inputs[i * 3 + 2];
        state = poseidon2_permutation(state, 4);
    }

    let remainder: u32 = M - full * 3;
    if (remainder != 0) | (M == 0) {
        for i in 0..remainder {
            state[i] += inputs[full * 3 + i];
        }
        state = poseidon2_permutation(state, 4);
    }

    state[0]
}

/// Single Poseidon2 entry point. Every higher-level helper in this crate
/// (`vk_from_sk`, `dvk_from_vk_op`, all `derive_*` / `encrypt_*`) routes through
/// this funnel so that the domain tag is always the *first* absorbed element.
///
/// Hashing raw -- bypassing this -- is a violation of the library contract.
pub fn poseidon_with_domain<let N: u32>(d: Field, inputs: [Field; N]) -> Field {
    let mut buf: [Field; N + 1] = [0; N + 1];
    buf[0] = d;
    for i in 0..N {
        buf[i + 1] = inputs[i];
    }
    sponge(buf)
}

// ################## KEY DERIVATION ##################

/// Viewing key. Section 4.2. `vk = Poseidon2(VK, sk, addr_f)`.
///
/// The `addr_f` parameter (the contract contract's address as a `Field`) binds the
/// viewing key -- and therefore every proof that constrains `vk` (R2/W2/T2/S2/V2)
/// -- to a specific deployed contract. Dropping `addr_f` here would let a proof for
/// one contract verify against another's verifier.
pub fn vk_from_sk(sk: Field, addr_f: Field) -> Field {
    poseidon_with_domain(domain::VIEWING_KEY, [sk, addr_f])
}

/// Public viewing key `PVK = vk*H`. Section 4.3. The recipient's ECDH long-term key
/// for incoming transfers.
pub fn pvk_from_vk(vk: Field) -> EmbeddedCurvePoint {
    scalar_mul(vk, H)
}

/// Delegation viewing key. Section 4.4. `dvk_i = Poseidon2(DVK, vk, op_i)`.
pub fn dvk_from_vk_op(vk: Field, op_i: Field) -> Field {
    poseidon_with_domain(domain::DELEGATION_VIEWING_KEY, [vk, op_i])
}

/// Deterministic randomness for the new spendable balance after an
/// owner-initiated proof operation. Constraints W5 / T10 / S9 / V6.
pub fn derive_spend_r(vk: Field, sigma: Field) -> Field {
    poseidon_with_domain(domain::SPEND_RANDOMNESS, [vk, sigma])
}

/// Deterministic randomness for the spender allowance commitment.
/// Constraints S6 / O3 / O10.
pub fn derive_allow_r(dvk: Field, sigma_a: Field) -> Field {
    poseidon_with_domain(domain::ALLOWANCE_RANDOMNESS, [dvk, sigma_a])
}

/// ECDH-derived blinding for the transfer commitment `C_transfer`.
/// Constraints T7 / O7. `s` is the recipient-ECDH shared-secret scalar
/// produced by [`ecdh`].
pub fn derive_transfer_blind(s: Field, sigma: Field) -> Field {
    poseidon_with_domain(domain::TRANSFER_BLINDING, [s, sigma])
}

// ################## ENCRYPTED SCALARS ##################

/// Encrypts the transfer amount under the recipient's ECDH shared secret.
/// Constraints T9 / O9. `v_tilde = v_transfer + Poseidon2(TRANSFER_AMOUNT, s, sigma)`.
pub fn encrypt_amount(v_transfer: Field, s: Field, sigma: Field) -> Field {
    v_transfer + poseidon_with_domain(domain::TRANSFER_AMOUNT, [s, sigma])
}

/// Encrypts the new spendable balance under the owner's viewing key.
/// Constraints W7 / T12 / S11 / V8. `b_tilde = v_new + Poseidon2(ENC_BAL, vk, sigma)`.
pub fn encrypt_balance(v_new: Field, vk: Field, sigma: Field) -> Field {
    v_new + poseidon_with_domain(domain::ENCRYPTED_BALANCE, [vk, sigma])
}

/// Encrypts the spender allowance under the delegation viewing key.
/// Constraints S8 / O12. `a_tilde = v_a + Poseidon2(ENC_ALLOW, dvk, sigma_a)`.
pub fn encrypt_allowance(v_a: Field, dvk: Field, sigma_a: Field) -> Field {
    v_a + poseidon_with_domain(domain::ENCRYPTED_ALLOWANCE, [dvk, sigma_a])
}

/// Delegation-key escrow mask for the spender handoff at `set_spender`. Section 7.11.
/// `escrowed_dvk = dvk + Poseidon2(ESC_DVK, s, op_i)` where `s = ecdh(r_e, Y_op)`.
pub fn encrypt_esc_dvk(dvk: Field, s: Field, op_i: Field) -> Field {
    dvk + poseidon_with_domain(domain::ESCROWED_DELEGATION_VIEWING_KEY, [s, op_i])
}

// ################## AUDITOR-CHANNEL SPONGE ##################

/// Poseidon2 sponge with two squeezes. Absorbs `(d, s_x, sigma)` -- where
/// `s_x` is the ECDH shared-secret scalar produced by [`ecdh`] -- and returns
/// the first two rate-elements of the post-permutation state in order.
///
/// Implements `SpongeSqueeze_2(delta, s, sigma)` from Section 2.5. The canonical
/// squeeze order is: index 0 = amount mask, index 1 = balance / randomness
/// mask, fixed by Sections 7 and 8. With rate = 3 the absorb fits one block
/// and both outputs are served from the same permutation, so the constraint
/// cost is exactly one Poseidon2 permutation per call.
///
/// Used by: Transfer (T_a2 recipient-auditor amount + randomness, T_a6
/// sender-auditor amount + balance) and SpenderTransfer (O_a2, O_a6).
pub fn sponge_squeeze_2(d: Field, s_x: Field, sigma: Field) -> [Field; 2] {
    let iv: Field = 3 * POSEIDON2_IV_BASE;
    let state = poseidon2_permutation([d, s_x, sigma, iv], 4);
    [state[0], state[1]]
}

/// Sender-auditor encrypted balance checkpoint for circuits whose auditor
/// block emits a single ciphertext (Withdraw W_a3/W_a4).
///
/// `b_tilde_aud_s = v_new + sponge_squeeze_2(AUDITOR_SENDER, s_a_s_x, sigma)[1]`,
/// where `s_a_s_x` is the sender-auditor ECDH shared-secret scalar produced by
/// [`ecdh`].
/// The pad is the sponge's *second* squeeze -- the slot every two-ciphertext
/// sender channel (Transfer T_a6-T_a8, SetSpender S_a3-S_a5, RevokeSpender
/// V_a3-V_a5, SpenderTransfer O_a6-O_a8) uses for its balance/allowance mask.
/// The first squeeze is reserved for amount masks, so a balance checkpoint
/// never shares a pad with an amount ciphertext even if a `(r_e, sigma)` pair
/// is mistakenly reused across operations (the pair must be unique per proof;
/// DESIGN Section 2.5).
pub fn encrypt_auditor_sender_balance(v_new: Field, s_a_s_x: Field, sigma: Field) -> Field {
    v_new + sponge_squeeze_2(domain::AUDITOR_SENDER, s_a_s_x, sigma)[1]
}

56.source:
use stellar_confidential_lib::{
    H, assert_on_curve_non_identity, commit, derive_spend_r, derive_transfer_blind, domain, ecdh,
    encrypt_amount, encrypt_balance, scalar_mul, sponge_squeeze_2, vk_from_sk,
};
use std::embedded_curve_ops::EmbeddedCurvePoint;

mod tests;

// Transfer circuit -- design doc Section 7.6.
//
// Constraints
// -----------
// Sender state (balance conservation + ownership)
//   T1  Y_A         = sk_A * H                              Sender key
//                                                           ownership.
//   T2  vk_A        = Poseidon2(delta_vk, sk_A, addr_f)       Contract-bound
//                                                           viewing key.
//   T3  C_spend^A   = v_A * G + r_A * H                     Opening of the
//                                                           sender's current
//                                                           spendable balance.
//   T4  v_A, v_transfer, v_A - v_transfer in [0, 2^127)                 Range validity
//                                                           (Section 2.6); the
//                                                           [0, 2^127) bound is
//                                                           the SEP-41 i128
//                                                           non-negative range
//                                                           (Section 3.4).
//   T10 r_A'        = Poseidon2(delta_spend_r, vk_A, sigma) Deterministic
//                                                           randomness for the
//                                                           new sender balance.
//   T11 C_spend'    = (v_A - v_transfer) * G + r_A' * H           New spendable
//                                                           commitment.
//   T12 b_tilde     = (v_A - v_transfer)
//                       + Poseidon2(delta_enc_bal, vk_A, sigma)
//                                                           Encrypted balance
//                                                           scalar (emitted).
// Recipient ECDH + transfer commitment (Section 5.3, 5.4)
//   T5  s           = ecdh(r_e, PVK_B)                      Recipient ECDH
//                                                           shared-secret
//                                                           scalar (2.4).
//   T6  R_e         = r_e * H                               Ephemeral public
//                                                           key.
//   T7  r_transfer        = Poseidon2(delta_transfer_blind, s, sigma)   Anti-poisoning
//                                                           binding: r_transfer is
//                                                           uniquely determined
//                                                           by (s, sigma).
//   T8  C_transfer        = v_transfer * G + r_transfer * H                   Transfer
//                                                           commitment.
//   T9  v_tilde     = v_transfer
//                       + Poseidon2(delta_transfer_amount, s, sigma)
//                                                           Encrypted amount
//                                                           (emitted).
//   T13 r_e != 0                                            Rules out R_e = O
//                                                           and S, S_{a,r},
//                                                           S_{a,s} = O.
// Auditor block (dual-channel visibility, Section 8.1)
//   T_a1 s_{a,r}    = ecdh(r_e, K_aud_r)                    Recipient-auditor
//                                                           ECDH shared scalar
//                                                           (reuses r_e).
//   T_a2 (m_v_r, m_r_r)
//                  = SpongeSqueeze_2(delta_aud_r,
//                                    s_{a,r}, sigma)        Recipient-channel
//                                                           sponge: two masks.
//   T_a3 v_tilde_aud_r = v_transfer + m_v_r                       Recipient-auditor
//                                                           encrypted amount.
//   T_a4 r_tilde_aud_r = r_transfer + m_r_r                       Recipient-auditor
//                                                           encrypted transfer
//                                                           randomness.
//   T_a5 s_{a,s}    = ecdh(r_e, K_aud_s)                    Sender-auditor ECDH
//                                                           shared scalar
//                                                           (reuses r_e).
//   T_a6 (m_v_s, m_b_s)
//                  = SpongeSqueeze_2(delta_aud_s,
//                                    s_{a,s}, sigma)        Sender-channel
//                                                           sponge: two masks.
//   T_a7 v_tilde_aud_s = v_transfer + m_v_s                       Sender-auditor
//                                                           encrypted amount.
//   T_a8 b_tilde_aud_s = (v_A - v_transfer) + m_b_s               Sender-auditor
//                                                           encrypted balance
//                                                           checkpoint.
//
// Point-validation doctrine (Section 10.8)
// ----------------------------------------
// Y_A, C_spend', C_transfer, R_e, S, S_{a,r}, and S_{a,s} are bound to in-circuit
// multi_scalar_mul outputs (T1, T11, T8, T6, T5, T_a1, T_a5) and are therefore
// on-curve by construction -- no explicit check needed. PVK_B was constrained
// on-curve when the recipient registered (R3, Section 7.2) and is loaded by
// the contract from trusted storage, so it is path (2) of Section 10.8 and the
// contract trusts it on read. K_aud_r and K_aud_s are public-input keys
// consumed by ECDH multiplications (path (3)); the verifier doesn't check
// curve membership and an off-curve auditor key would break the soundness of
// T_a1 / T_a5, so this file explicitly validates both on-curve AND
// non-identity before the auditor block runs.
//
// Public inputs (24 fields, in design-doc canonical order)
// --------------------------------------------------------
//   Idx  Param            Symbol          Source / Note
//   ---  -----            ------          -----------------------------------
//   0    c_spend_x        C_spend^A.x     Loaded from `from.spendable_commitment`.
//   1    c_spend_y        C_spend^A.y
//   2    y_x              Y_A.x           Loaded from `from.spending_public_key`.
//   3    y_y              Y_A.y
//   4    pvk_b_x          PVK_B.x         Loaded from `to.viewing_public_key`.
//   5    pvk_b_y          PVK_B.y           Recipient must be registered.
//   6    addr_f             addr_f            `env.current_contract_address()`.
//   7    k_aud_r_x        K_aud_r.x       Fetched from the auditor contract by
//   8    k_aud_r_y        K_aud_r.y         `to.auditor_id`.
//   9    k_aud_s_x        K_aud_s.x       Fetched from the auditor contract by
//   10   k_aud_s_y        K_aud_s.y         `from.auditor_id`.
//   11   c_spend_new_x    C_spend'.x      Prover-supplied; written to
//   12   c_spend_new_y    C_spend'.y        `from.spendable_commitment`.
//   13   c_transfer_x           C_transfer.x          Prover-supplied; added to
//   14   c_transfer_y           C_transfer.y            `to.receiving_commitment`.
//   15   r_e_x            R_e.x           Prover-supplied ephemeral key;
//   16   r_e_y            R_e.y             emitted.
//   17   v_tilde          v_tilde         Prover-supplied encrypted amount;
//                                         emitted.
//   18   b_tilde          b_tilde         Prover-supplied encrypted balance
//                                         scalar; emitted.
//   19   sigma            sigma           Prover-supplied random salt; emitted.
//   20   v_tilde_aud_r    v_tilde_aud_r   Prover-supplied recipient-auditor
//                                         encrypted amount; emitted.
//   21   r_tilde_aud_r    r_tilde_aud_r   Prover-supplied recipient-auditor
//                                         encrypted transfer randomness;
//                                         emitted.
//   22   v_tilde_aud_s    v_tilde_aud_s   Prover-supplied sender-auditor
//                                         encrypted amount; emitted.
//   23   b_tilde_aud_s    b_tilde_aud_s   Prover-supplied sender-auditor
//                                         encrypted balance checkpoint;
//                                         emitted.
//
// Private witnesses
// -----------------
//   sk     Sender's spending secret scalar.
//   v      Plaintext sender spendable-balance value.
//   r      Plaintext blinding factor for C_spend^A.
//   v_transfer   Plaintext transfer amount.
//   r_e    Ephemeral scalar for recipient + auditor ECDH; must satisfy
//          r_e != 0 (T13).

fn main(
    sk: Field,
    v: Field,
    r: Field,
    v_transfer: Field,
    r_e: Field,
    c_spend_x: pub Field,
    c_spend_y: pub Field,
    y_x: pub Field,
    y_y: pub Field,
    pvk_b_x: pub Field,
    pvk_b_y: pub Field,
    addr_f: pub Field,
    k_aud_r_x: pub Field,
    k_aud_r_y: pub Field,
    k_aud_s_x: pub Field,
    k_aud_s_y: pub Field,
    c_spend_new_x: pub Field,
    c_spend_new_y: pub Field,
    c_transfer_x: pub Field,
    c_transfer_y: pub Field,
    r_e_x: pub Field,
    r_e_y: pub Field,
    v_tilde: pub Field,
    b_tilde: pub Field,
    sigma: pub Field,
    v_tilde_aud_r: pub Field,
    r_tilde_aud_r: pub Field,
    v_tilde_aud_s: pub Field,
    b_tilde_aud_s: pub Field,
) {
    // T13 -- runs first so the r_e = 0 attack is rejected before any
    // scalar mul against it could quietly produce the identity.
    assert(r_e != 0);

    // T1
    let y_derived = scalar_mul(sk, H);
    assert(y_derived.x == y_x);
    assert(y_derived.y == y_y);

    // T2
    let vk = vk_from_sk(sk, addr_f);

    // T3
    let c_spend_derived = commit(v, r);
    assert(c_spend_derived.x == c_spend_x);
    assert(c_spend_derived.y == c_spend_y);

    // T4 -- Section 2.6 spells out the 127-bit decomposition / recomposition
    // pattern; `assert_max_bit_size` is the Noir stdlib primitive that
    // implements it directly.
    v.assert_max_bit_size::<127>();
    v_transfer.assert_max_bit_size::<127>();
    let v_new = v - v_transfer;
    v_new.assert_max_bit_size::<127>();

    // T6
    let r_e_derived = scalar_mul(r_e, H);
    assert(r_e_derived.x == r_e_x);
    assert(r_e_derived.y == r_e_y);

    // T5 -- PVK_B is path (2) of Section 10.8 (proof-constrained at the
    // recipient's registration, trusted on read).
    let pvk_b = EmbeddedCurvePoint { x: pvk_b_x, y: pvk_b_y, is_infinite: false };
    let s_x = ecdh(r_e, pvk_b);

    // T7 (anti-poisoning, Section 5.4)
    let r_transfer = derive_transfer_blind(s_x, sigma);

    // T8
    let c_transfer_derived = commit(v_transfer, r_transfer);
    assert(c_transfer_derived.x == c_transfer_x);
    assert(c_transfer_derived.y == c_transfer_y);

    // T9
    let v_tilde_derived = encrypt_amount(v_transfer, s_x, sigma);
    assert(v_tilde_derived == v_tilde);

    // T10
    let r_new = derive_spend_r(vk, sigma);

    // T11
    let c_spend_new_derived = commit(v_new, r_new);
    assert(c_spend_new_derived.x == c_spend_new_x);
    assert(c_spend_new_derived.y == c_spend_new_y);

    // T12
    let b_tilde_derived = encrypt_balance(v_new, vk, sigma);
    assert(b_tilde_derived == b_tilde);

    // K_aud_r / K_aud_s point validation (Section 10.8: public-input keys).
    let k_aud_r = EmbeddedCurvePoint { x: k_aud_r_x, y: k_aud_r_y, is_infinite: false };
    assert_on_curve_non_identity(k_aud_r);
    let k_aud_s = EmbeddedCurvePoint { x: k_aud_s_x, y: k_aud_s_y, is_infinite: false };
    assert_on_curve_non_identity(k_aud_s);

    // T_a1 (recipient-auditor shared-secret scalar)
    let s_a_r_x = ecdh(r_e, k_aud_r);

    // T_a2 (recipient-channel masks: amount, then r_transfer)
    let m_r = sponge_squeeze_2(domain::AUDITOR_RECIPIENT, s_a_r_x, sigma);

    // T_a3
    assert(v_transfer + m_r[0] == v_tilde_aud_r);

    // T_a4
    assert(r_transfer + m_r[1] == r_tilde_aud_r);

    // T_a5 (sender-auditor shared-secret scalar)
    let s_a_s_x = ecdh(r_e, k_aud_s);

    // T_a6 (sender-channel masks: amount, then balance)
    let m_s = sponge_squeeze_2(domain::AUDITOR_SENDER, s_a_s_x, sigma);

    // T_a7
    assert(v_transfer + m_s[0] == v_tilde_aud_s);

    // T_a8
    assert(v_new + m_s[1] == b_tilde_aud_s);
}
